/// <summary>
/// designed from AVA
/// </summary>
/// <returns>container</returns>
public container pack()
{
    return [#CurrentVersion, #CurrentList];
}

/// <summary>
/// designed from AVA
/// </summary>
/// <param name = "packedClass">packedClass</param>
/// <returns>boolean</returns>
public boolean unpack(container packedClass)
{
    Version version = runbase::getVersion(packedClass);
    switch (version)
    {
        case #CurrentVersion:
            [version, #CurrentList] = packedClass;
            break;
        default:
            return false;
    }

    return true;
}

/// <summary>
/// designed from AVA
/// </summary>
/// <param name = "_args">_args</param>
/// <returns>AVACreateQuotationJournal</returns>
static AVACreateQuotationJournal construct(Args _args)
{
    AVACreateQuotationJournal createQuotationJournal = new AVACreateQuotationJournal();

    createQuotationJournal.parmDocumentStatus(_args.parmEnum());
    createQuotationJournal.parmSalesProj(_args.parm());
    createQuotationJournal.parmSalesQuotationTable(_args.record());
    createQuotationJournal.parmSendMode(_args.parm() != 'GAEB' ? KCS_SendMode::Email : KCS_SendMode::GAEB);

    return createQuotationJournal;
}

